<?php
namespace App\Http\Controllers;
use App\Models\Subscription; use App\Models\SubscriptionPlan; use App\Support\Workspace; use Illuminate\Http\Request; use Illuminate\Support\Facades\Http;
class BillingController extends Controller {
    public function index(Request $request) { $business=Workspace::business($request); return view('billing.index',['business'=>$business,'subscription'=>$business->subscription()->with('plan')->first(),'plans'=>SubscriptionPlan::where('active',true)->get(),'configured'=>(bool)config('services.paypal.client_id')]); }
    public function checkout(Request $request,SubscriptionPlan $plan) { $b=Workspace::business($request); abort_unless($plan->active && $plan->paypal_plan_id,422,'This plan is not configured for PayPal checkout yet.'); abort_unless(config('services.paypal.client_id')&&config('services.paypal.secret'),422,'PayPal is not configured.'); $token=$this->accessToken(); $response=Http::withToken($token)->acceptJson()->post(rtrim(config('services.paypal.base_url'),'/').'/v1/billing/subscriptions',['plan_id'=>$plan->paypal_plan_id,'application_context'=>['brand_name'=>config('app.name'),'user_action'=>'SUBSCRIBE_NOW','return_url'=>route('billing.return'),'cancel_url'=>route('billing.index')]]); abort_unless($response->successful(),502,'PayPal could not start checkout. Check the configured Sandbox credentials and plan ID.'); $body=$response->json(); Subscription::updateOrCreate(['business_id'=>$b->id],['subscription_plan_id'=>$plan->id,'provider'=>'paypal','provider_subscription_id'=>$body['id'],'status'=>'pending']); $approval=collect($body['links']??[])->firstWhere('rel','approve')['href']??null; abort_unless($approval,502,'PayPal did not return an approval link.'); return redirect()->away($approval); }
    public function returned(Request $request) { return redirect()->route('billing.index')->with('status','We received your return from PayPal. Your subscription status will update only after PayPal verifies the subscription or sends its webhook.'); }
    public function cancel(Request $request) { $b=Workspace::business($request); $sub=$b->subscription; abort_unless($sub?->provider_subscription_id,422,'No PayPal subscription is linked to this workspace.'); $response=Http::withToken($this->accessToken())->post(rtrim(config('services.paypal.base_url'),'/').'/v1/billing/subscriptions/'.$sub->provider_subscription_id.'/cancel',['reason'=>'Cancelled by business owner']); abort_unless($response->successful(),502,'PayPal could not cancel the subscription.'); $sub->update(['status'=>'cancelled']); return back()->with('status','Cancellation requested with PayPal.'); }
    private function accessToken(): string { $response=Http::asForm()->withBasicAuth(config('services.paypal.client_id'),config('services.paypal.secret'))->post(rtrim(config('services.paypal.base_url'),'/').'/v1/oauth2/token',['grant_type'=>'client_credentials']); abort_unless($response->successful(),502,'Unable to authenticate with PayPal.'); return $response->json('access_token'); }
}
